/// <summary>
/// CB705_VendorRebatePosting
/// </summary>
[ExtensionOf(classStr(TAMRebateCreateDocument))]
final class METTAMRebateCreateDocument_Extension
{
    public TAMRebateDeal METRebateDeal;
    public List metHeaderList;

}

Method.Source:
/// <summary>
/// When <c>TAMRebateDateTrans</c> is set, retrieve the corresponding <c>TAMRebateDeal</c> record.
/// This will be used in METTAMRebateCreateDocumentFinancialLedgerJournal_Extension\METApplyConsolidationByVendorRebateType
/// </summary>
/// <param name = "_rebateDateTrans"><c>TAMRebateDateTrans</c> record</param>
/// <returns><c>TAMRebateDateTrans</c> record</returns>
public TAMRebateDateTrans parmRebateDateTrans(TAMRebateDateTrans _rebateDateTrans)
{
    TAMRebateDateTrans localRebateDateTrans = next parmRebateDateTrans(_rebateDateTrans);

    if (_rebateDateTrans)
    {
        METRebateDeal = TAMRebateDeal::find(_rebateDateTrans.RebateDeal);
    }

    return localRebateDateTrans;
}

/// <summary>
/// Create header for rebate transactions
/// </summary>
/// <returns>Table buffer</returns>
public Common createHeader()
{
    Common documentHeader = next createHeader();

    this.parmMETHeaderList(this.headerList);

    return documentHeader;
}

/// <summary>
/// This will be used in capture the headerlist
/// </summary>
/// <param name = "_headerList">Header list</param>
/// <returns><c>Header list</returns>
public List parmMETHeaderList(List _headerList = metHeaderList)
{
    metHeaderList = _headerList;
    return metHeaderList;
}
